type SellerVariation = {
  id: number;
  name: string;
  price: number;
  stock: number;
};

type SellerProduct = {
  id: number;
  name: string;
  thumbnail: string;
  variations: SellerVariation[];
};

// TODO: sau này thay bằng API cho seller (accountId = 1)
